data:
/* === Consolidated wiki polish: layout, accessibility, status and responsive UI === */
.directory-heading > div > span {
  display: block;
  margin-top: 7px;
  color: #8a7c76;
  font-size: 11px;
  line-height: 1.55;
}

.directory-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.directory-card {
  grid-template-columns: 84px minmax(0, 1fr) 22px;
  min-height: 122px;
  padding: 16px;
  gap: 14px;
  border-color: rgba(255,255,255,.055);
  border-radius: 17px;
  background: rgba(255,255,255,.018);
  transition: transform .18s ease, border-color .18s ease, background .18s ease, box-shadow .18s ease;
}

.directory-media {
  position: relative;
  width: 84px;
  height: 84px;
  overflow: hidden;
  border-radius: 15px;
  font-size: 28px;
}

.directory-media img,
.related-doc-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.directory-media.is-icon {
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.11);
  background:
    radial-gradient(circle at 35% 30%, rgba(var(--accent-rgb),.16), transparent 34%),
    linear-gradient(145deg, rgba(var(--gold-rgb),.12), rgba(var(--accent-rgb),.035)),
    rgba(255,255,255,.018);
}

.directory-media.is-icon::after {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(var(--gold-rgb),.08);
  border-radius: 11px;
  pointer-events: none;
}

.directory-copy {
  align-content: center;
  gap: 7px;
}

.directory-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.directory-title-row strong {
  font-size: 15px;
}

.directory-title-row em {
  padding: 3px 7px;
  border: 1px solid rgba(var(--gold-rgb),.2);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.07);
  color: #cda25e;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: .04em;
}

.directory-copy small {
  font-size: 11px;
}

.directory-arrow {
  align-self: center;
  font-size: 17px;
}

.directory-card.is-featured {
  border-color: rgba(var(--accent-rgb),.24);
  background:
    linear-gradient(135deg, rgba(var(--accent-rgb),.075), rgba(var(--gold-rgb),.035) 58%, transparent 82%),
    rgba(255,255,255,.024);
  box-shadow: inset 3px 0 0 rgba(var(--accent-rgb),.62), 0 8px 26px rgba(0,0,0,.1);
}

.directory-card.is-featured .directory-title-row strong {
  color: #f3e7e1;
}

.directory-card.is-featured .directory-title-row em {
  border-color: rgba(var(--accent-rgb),.26);
  background: rgba(var(--accent-rgb),.09);
  color: #ee857a;
}

.directory-card.is-draft {
  border-style: dashed;
  border-color: rgba(var(--gold-rgb),.13);
  background: rgba(255,255,255,.012);
}

.directory-card.is-draft .directory-media {
  filter: saturate(.62);
  opacity: .76;
}

.directory-card.is-draft .directory-title-row em {
  border-color: rgba(160,147,140,.18);
  background: rgba(160,147,140,.07);
  color: #9e918b;
}

.directory-card:not(.is-featured):hover,
.recent-update-card:hover,
.related-doc-card:hover {
  transform: translateY(-1px);
  border-color: rgba(var(--gold-rgb),.17);
  background: rgba(var(--gold-rgb),.028);
}

.directory-card.is-featured:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--accent-rgb),.36);
  box-shadow: inset 3px 0 0 rgba(var(--accent-rgb),.78), 0 12px 28px rgba(0,0,0,.14);
}

.starter-guide,
.wiki-directory,
.recent-updates,
.related-docs,
.document-card {
  border-color: rgba(255,255,255,.055);
  box-shadow: 0 8px 24px rgba(0,0,0,.11);
}

.starter-step,
.recent-update-card,
.related-doc-card {
  border-color: rgba(255,255,255,.055);
  background: rgba(255,255,255,.018);
  transition: transform .18s ease, border-color .18s ease, background .18s ease, box-shadow .18s ease;
}

.starter-step {
  isolation: isolate;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  background:
    radial-gradient(circle at 85% 15%, rgba(var(--gold-rgb),.08), transparent 42%),
    rgba(255,255,255,.024);
}

.starter-step:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--accent-rgb),.22);
  box-shadow: 0 10px 22px rgba(0,0,0,.12);
}


.starter-number {
  grid-column: 1 / -1;
}

.starter-icon {
  align-self: center;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(var(--gold-rgb),.13);
  border-radius: 13px;
  background: rgba(var(--gold-rgb),.055);
  font-size: 21px;
}

.starter-copy {
  min-width: 0;
  padding: 8px 0;
}

.starter-target {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 7px;
}

.starter-target em {
  padding: 2px 6px;
  border: 1px solid rgba(160,147,140,.16);
  border-radius: 999px;
  color: #978a84;
  font-size: 8px;
  font-style: normal;
  font-weight: 800;
}

.wiki-main {
  gap: 21px;
}

.wiki-hero.has-hero-image.is-home {
  min-height: 330px;
}

.hero-search-cta {
  width: min(100%, 620px);
}

.wiki-hero.is-article {
  min-height: 0;
  padding: 18px 26px;
}

.wiki-hero.is-article .hero-copy h1 {
  font-size: clamp(26px, 3vw, 34px);
}

.hero-background-image {
  display: block;
  overflow: hidden;
  background: none;
  transform: none;
}

.hero-background-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  transform: scale(1.01);
}

.sidebar-primary-links {
  margin-bottom: 2px;
}

.toc-list {
  scrollbar-width: thin;
  scrollbar-color: rgba(170,157,151,.22) transparent;
}

.toc-list::-webkit-scrollbar {
  width: 5px;
}

.toc-list::-webkit-scrollbar-track {
  background: transparent;
}

.toc-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(170,157,151,.16);
}

.toc-list:hover::-webkit-scrollbar-thumb {
  background: rgba(var(--gold-rgb),.34);
}

.sidebar-category {
  display: grid;
  gap: 7px;
  margin-top: 17px;
}

.sidebar-category:first-of-type {
  margin-top: 8px;
}

.sidebar-category-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px 4px;
}

.sidebar-category-head strong {
  color: #a49791;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: .055em;
}

.sidebar-category-head span {
  color: #756963;
  font-size: 10px;
}

.sidebar-category-links {
  display: grid;
  gap: 2px;
}

.nav-section-label {
  font-size: 10px;
  letter-spacing: .09em;
}

.global-page-link {
  min-height: 38px;
  gap: 9px;
}

.sidebar-page-icon {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--gold-rgb),.08);
  border-radius: 8px;
  background: rgba(var(--gold-rgb),.035);
  font-size: 13px;
}

.global-page-link:hover .sidebar-page-icon,
.global-page-link.is-current .sidebar-page-icon {
  border-color: rgba(var(--accent-rgb),.18);
  background: rgba(var(--accent-rgb),.075);
}

.global-page-link.is-current {
  background: linear-gradient(90deg, rgba(var(--accent-rgb),.16), rgba(var(--accent-rgb),.055));
  color: #f4a198;
  box-shadow:
    inset 3px 0 0 rgba(var(--accent-rgb),.92),
    inset 0 0 0 1px rgba(var(--accent-rgb),.1),
    0 5px 18px rgba(0,0,0,.08);
}

.global-page-link.is-current .global-page-copy strong {
  color: #fff1ed;
  font-weight: 850;
}

.sidebar-edge-toggle {
  display: none;
}

.article-toc {
  width: 220px;
  padding-left: 18px;
}

.article-toc-label {
  font-size: 11px;
}

.article-toc-item {
  padding-block: 7px;
  font-size: 12px;
  line-height: 1.5;
}

.article-progress {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
  color: #786b66;
  font-size: 11px;
}

.article-progress strong {
  color: #b99b73;
  font-size: 11px;
}

.article-progress-track {
  position: absolute;
  left: -1px;
  top: 15px;
  bottom: 15px;
  width: 2px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(var(--gold-rgb),.08);
}

.article-progress-track span {
  display: block;
  width: 100%;
  min-height: 2px;
  border-radius: inherit;
  background: linear-gradient(180deg, #d7aa62, #d95447);
  transition: height .16s ease-out;
}

.recent-update-card {
  min-height: 116px;
  align-content: start;
}

.recent-update-date {
  color: #a4938c;
  font-size: 11px;
}

.recent-update-card strong {
  font-size: 14px;
  line-height: 1.4;
}

.recent-update-summary {
  display: -webkit-box;
  padding-right: 18px;
  overflow: hidden;
  color: #a99a93;
  font-size: 12px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.related-doc-image {
  overflow: hidden;
  background: linear-gradient(135deg, rgba(var(--accent-rgb),.1), rgba(var(--gold-rgb),.08));
}

.search-result-card.is-selected {
  background: rgba(var(--accent-rgb),.11);
  box-shadow: inset 2px 0 0 rgba(var(--accent-rgb),.72);
}

.search-result-category {
  width: max-content;
  padding: 2px 6px;
  border: 1px solid rgba(var(--gold-rgb),.14);
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.045);
  color: #b18e63;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
}

.search-result-card[data-category="주요 콘텐츠"] .search-result-category {
  border-color: rgba(var(--accent-rgb),.18);
  background: rgba(var(--accent-rgb),.055);
  color: #d87b71;
}

.search-result-card[data-category="성장 · 경제"] .search-result-category {
  border-color: rgba(194,126,56,.18);
  background: rgba(194,126,56,.055);
  color: #c8945e;
}

.draft-notice {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border: 1px dashed rgba(var(--gold-rgb),.22);
  border-radius: 14px;
  background: rgba(var(--gold-rgb),.035);
}

.draft-notice > span {
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(var(--gold-rgb),.08);
  color: #c7a169;
  font-size: 10px;
  font-weight: 850;
}

.draft-notice > div {
  display: grid;
  gap: 3px;
}

.draft-notice strong {
  font-size: 13px;
}

.draft-notice small {
  color: #8e817b;
  font-size: 11px;
}

.status-services {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.status-services article {
  min-height: 118px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 17px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 15px;
  background: rgba(15,20,28,.82);
}

.status-service-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: rgba(var(--gold-rgb),.07);
  color: #d6a85f;
  font-size: 18px;
}

.status-services article > div {
  display: grid;
  gap: 4px;
}

.status-services small,
.status-services a {
  font-size: 9px;
}

.status-services small {
  color: #746762;
}

.status-services strong {
  font-size: 14px;
}

.status-services span {
  color: #8a7c76;
  font-size: 10px;
}

.status-services a {
  color: #96877f;
  text-decoration: none;
}

.status-services article[data-tone="success"] {
  border-color: rgba(111,185,131,.18);
}

.status-services article[data-tone="warning"] {
  border-color: rgba(var(--accent-rgb),.3);
}

.status-services article[data-tone="working"] {
  border-color: rgba(var(--gold-rgb),.2);
}

.status-dot.is-warning {
  background: #df6b5f;
  box-shadow: 0 0 14px rgba(223,107,95,.55);
}

.status-asset-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 15px;
  background: rgba(15,20,28,.72);
}

.status-asset-metrics > div {
  min-height: 90px;
  padding: 16px;
  display: grid;
  align-content: center;
  gap: 5px;
}

.status-asset-metrics > div + div {
  border-left: 1px solid rgba(255,255,255,.06);
}

.status-asset-metrics small {
  color: #746762;
  font-size: 9px;
}

.status-asset-metrics strong {
  font-size: 18px;
}

.status-recent-list a > span:first-child {
  display: grid;
  gap: 4px;
}

.status-recent-list small {
  max-width: 700px;
  overflow: hidden;
  color: #7f716b;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wiki-directory,
.recent-updates,
.related-docs {
  content-visibility: auto;
  contain-intrinsic-size: auto 760px;
}

.directory-group {
  content-visibility: auto;
  contain-intrinsic-size: auto 430px;
}

.starter-step:focus-visible,
.directory-card:focus-visible,
.recent-update-card:focus-visible,
.related-doc-card:focus-visible,
.sidebar-edge-toggle:focus-visible {
  outline: 2px solid rgba(var(--gold-rgb),.7);
  outline-offset: 2px;
}

@media (min-width: 981px) {
  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5) {
    min-height: 142px;
  }

  .recent-update-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 11px;
  }

  .sidebar-edge-toggle {
    position: fixed;
    z-index: 36;
    top: calc(var(--topbar) + 19px);
    left: calc(var(--sidebar) - 14px);
    width: 29px;
    height: 44px;
    display: grid;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(var(--gold-rgb),.15);
    border-radius: 0 11px 11px 0;
    background: rgba(15,12,13,.97);
    color: #b5a7a0;
    cursor: pointer;
    box-shadow: 5px 8px 20px rgba(0,0,0,.18);
    transition: left .24s cubic-bezier(.2,.75,.25,1), width .18s ease, border-radius .18s ease, color .18s ease, background .18s ease;
  }

  .sidebar-edge-toggle:hover {
    border-color: rgba(var(--gold-rgb),.3);
    background: rgba(var(--gold-rgb),.075);
    color: #e5c487;
  }

  .sidebar-toggle-expanded {
    font-size: 22px;
    line-height: 1;
  }

  .sidebar-toggle-collapsed {
    display: none;
    align-items: center;
    gap: 6px;
  }

  .sidebar-toggle-collapsed b {
    font-size: 14px;
  }

  .sidebar-toggle-collapsed em {
    font-size: 10px;
    font-style: normal;
    font-weight: 800;
  }

  .wiki-sidebar {
    transition: transform .24s cubic-bezier(.2,.75,.25,1), opacity .18s ease;
  }

  .wiki-main {
    transition: padding-left .24s cubic-bezier(.2,.75,.25,1), padding-right .24s cubic-bezier(.2,.75,.25,1);
  }

  html[data-sidebar="collapsed"] .wiki-sidebar,
  .wiki-shell.is-sidebar-collapsed .wiki-sidebar {
    transform: translateX(calc(-100% - 8px));
    opacity: 0;
    pointer-events: none;
  }

  html[data-sidebar="collapsed"] .wiki-main,
  .wiki-shell.is-sidebar-collapsed .wiki-main {
    padding-left: 32px;
  }

  html[data-sidebar="collapsed"] .wiki-main.has-article-toc,
  .wiki-shell.is-sidebar-collapsed .wiki-main.has-article-toc {
    padding-left: 250px;
    padding-right: 250px;
  }

  html[data-sidebar="collapsed"] .sidebar-edge-toggle,
  .wiki-shell.is-sidebar-collapsed .sidebar-edge-toggle {
    left: 14px;
    width: 70px;
    border-radius: 11px;
  }

  html[data-sidebar="collapsed"] .sidebar-toggle-expanded,
  .wiki-shell.is-sidebar-collapsed .sidebar-toggle-expanded {
    display: none;
  }

  html[data-sidebar="collapsed"] .sidebar-toggle-collapsed,
  .wiki-shell.is-sidebar-collapsed .sidebar-toggle-collapsed {
    display: inline-flex;
  }
}

@media (min-width: 1320px) {
  .starter-steps {
    position: relative;
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5),
  .starter-step:last-child {
    grid-column: auto;
    min-height: 146px;
  }

  .starter-step:not(:last-child)::after {
    content: "›";
    position: absolute;
    z-index: 4;
    top: 50%;
    right: -10px;
    transform: translateY(-50%);
    color: rgba(var(--gold-rgb),.46);
    font-size: 18px;
    pointer-events: none;
  }
}

@media (max-width: 1279px) {
  .article-toc {
    display: none;
  }

  .mobile-current-toc {
    display: grid;
  }
}

@media (max-width: 1180px) {
  .directory-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .wiki-topbar,
  .wiki-sidebar,
  .hero-badge,
  .hero-search-cta,
  .search-modal-backdrop {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .wiki-topbar {
    background: rgba(10,9,10,.97);
  }

  .wiki-sidebar {
    background: rgba(13,11,12,.985);
  }

  .wiki-hero.has-hero-image.is-home {
    min-height: 315px;
  }

  .wiki-hero.is-article {
    padding: 17px 20px;
  }

  .starter-guide,
  .wiki-directory,
  .recent-updates,
  .related-docs,
  .document-card {
    box-shadow: none !important;
  }

  .starter-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .starter-step,
  .starter-step:nth-child(4),
  .starter-step:nth-child(5) {
    grid-column: auto;
  }

  .starter-step:last-child {
    grid-column: span 2;
  }
}

@media (max-width: 760px) {
  .directory-grid,
  .status-services,
  .status-asset-metrics {
    grid-template-columns: 1fr;
  }

  .directory-card {
    grid-template-columns: 72px minmax(0, 1fr) 20px;
    min-height: 104px;
    padding: 14px;
  }

  .directory-media {
    width: 72px;
    height: 72px;
  }

  .directory-title-row strong {
    font-size: 14px;
  }

  .status-asset-metrics > div + div {
    border-left: 0;
    border-top: 1px solid rgba(255,255,255,.06);
  }
}

@media (max-width: 620px) {
  .wiki-topbar {
    min-height: var(--topbar);
  }

  .menu-button,
  .header-search-button,
  .theme-toggle {
    min-width: 44px;
    width: 44px;
    min-height: 44px;
    height: 44px;
    display: grid;
    place-items: center;
  }

  .menu-button {
    padding: 0;
  }

  .top-actions {
    gap: 6px;
  }

  .wiki-main {
    gap: 16px;
  }

  .wiki-hero.has-hero-image.is-home {
    min-height: 300px;
    padding: 18px;
  }

  .hero-copy h1 {
    font-size: 29px;
  }

  .hero-copy > p:last-of-type {
    font-size: 12px;
    line-height: 1.6;
  }

  .hero-search-cta {
    min-height: 46px;
    margin-top: 14px;
  }

  .wiki-hero.is-article {
    padding: 14px 16px;
    border-radius: 15px;
  }

  .wiki-hero.is-article .hero-copy h1 {
    font-size: 26px;
  }

  .starter-guide {
    padding: 15px;
  }

  .starter-guide-head {
    margin-bottom: 11px;
  }

  .starter-steps {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .starter-step,
  .starter-step:last-child {
    min-height: 72px;
    grid-column: auto;
    grid-template-columns: 34px minmax(0, 1fr) 18px;
    grid-template-rows: auto auto;
    column-gap: 10px;
    row-gap: 2px;
    padding: 10px 11px;
  }

  .starter-number {
    grid-column: 1;
    grid-row: 1 / 3;
    align-self: center;
    font-size: 12px;
  }

  .starter-icon {
    display: none;
  }

  .starter-copy {
    grid-column: 2;
    grid-row: 1;
    align-content: end;
    padding: 0;
  }

  .starter-copy strong {
    font-size: 14px;
  }

  .starter-copy small {
