/* === Content maturity, recent history and mobile navigation === */
.directory-card.is-brief {
  border-color: rgba(var(--gold-rgb),.14);
  background:
    linear-gradient(135deg, rgba(var(--gold-rgb),.045), transparent 68%),
    rgba(255,255,255,.015);
}

.directory-card.is-brief .directory-title-row em {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.055);
  color: #c7a169;
}

.directory-drafts {
  margin-top: 12px;
  border-top: 1px dashed rgba(var(--gold-rgb),.12);
}

.directory-drafts > summary {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 4px 8px;
  color: #9b8d87;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.directory-drafts > summary::-webkit-details-marker {
  display: none;
}

.directory-drafts > summary::after {
  content: "⌄";
  margin-left: auto;
  color: #8f817b;
  transition: transform .18s ease;
}

.directory-drafts[open] > summary::after {
  transform: rotate(180deg);
}

.directory-drafts > summary span {
  font-size: 11px;
  font-weight: 800;
}

.directory-drafts > summary small {
  margin-left: auto;
  color: #776b66;
  font-size: 10px;
}

.directory-grid.is-drafts {
  padding-top: 4px;
  padding-bottom: 4px;
}

.sidebar-category-head {
  width: 100%;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: left;
}

.sidebar-category-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sidebar-category-meta b {
  display: none;
  color: #887a74;
  font-size: 12px;
  font-weight: 700;
  transition: transform .16s ease;
}

.recent-viewed {
  width: min(100%, var(--content-max));
  margin: 0 auto;
  padding: 16px 18px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 16px;
  background: rgba(255,255,255,.014);
}

.recent-viewed-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 10px;
}

.recent-viewed-head p {
  margin: 0 0 3px;
  color: #ad8957;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .12em;
}

.recent-viewed-head h2 {
  margin: 0;
  font-size: 16px;
}

.recent-viewed-head > small {
  color: var(--text-subtle);
  font-size: 10px;
}

.recent-viewed-list {
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  gap: 8px;
}

.recent-viewed-card {
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr) 16px;
  align-items: center;
  gap: 7px;
  padding: 9px 10px;
  border: 1px solid rgba(255,255,255,.05);
  border-radius: 11px;
  background: rgba(255,255,255,.018);
  color: inherit;
  text-decoration: none;
}

.recent-viewed-card > span {
  display: grid;
  place-items: center;
  font-size: 14px;
}

.recent-viewed-card strong {
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.recent-viewed-card b {
  color: #71655f;
  font-size: 11px;
}

.recent-viewed-card:hover {
  border-color: rgba(var(--gold-rgb),.18);
  background: rgba(var(--gold-rgb),.035);
}

.recent-update-date {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.recent-update-date > small {
  color: var(--text-subtle);
