.search-loading-row i {
  width: 40px;
  height: 40px;
  border-radius: 10px;
}

.search-loading-row b {
  width: 62%;
  height: 12px;
}

.search-loading-row em {
  width: 40px;
  height: 9px;
}

.mobile-toc-backdrop {
  display: none;
}

