export function MobileTocSheet({
  toc,
  readingProgress,
  activeTocId,
  onClose,
  onNavigate
}: {
  toc: ReadingTocItem[]
  readingProgress: number
  activeTocId: string
  onClose: () => void
  onNavigate: (id: string) => void
}) {
  const sheetRef = useRef<HTMLElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)

  useEffect(() => {
    track('wiki_mobile_toc_open')
    returnFocusRef.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const frame = requestAnimationFrame(() => closeRef.current?.focus())

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        onClose()
        return
      }

      if (event.key !== 'Tab' || !sheetRef.current) return

      const focusable = Array.from(
        sheetRef.current.querySelectorAll<HTMLElement>(
          'button, a[href], [tabindex]:not([tabindex="-1"])'
        )
      ).filter((element) => !element.hasAttribute('disabled'))

      if (!focusable.length) return

      const first = focusable[0]
      const last = focusable[focusable.length - 1]

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    window.addEventListener('keydown', onKeyDown)

    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
      requestAnimationFrame(() => returnFocusRef.current?.focus())
    }
  }, [onClose])

  return (
    <div
      className="mobile-toc-backdrop"
      role="presentation"
      onMouseDown={(event) => {
        if (event.currentTarget === event.target) onClose()
      }}
    >
      <section
        ref={sheetRef}
        className="mobile-toc-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="mobile-toc-title"
      >
        <div className="mobile-toc-handle" aria-hidden="true" />
        <header>
          <div>
            <small>현재 문서</small>
            <strong id="mobile-toc-title">목차</strong>
          </div>
          <button
            ref={closeRef}
            type="button"
            aria-label="목차 닫기"
            onClick={onClose}
          >
            ×
          </button>
        </header>
        <div className="mobile-toc-progress">
          <span>읽는 중</span>
          <b>{readingProgress}%</b>
        </div>
        <nav>
          {toc.map((item) => (
            <button
              key={item.id}
              type="button"
              className={`mobile-toc-item level-${item.level} ${activeTocId === item.id ? 'is-active' : ''}`}
              aria-current={activeTocId === item.id ? 'location' : undefined}
              onClick={() => {
                track('wiki_mobile_toc_navigate')
                onNavigate(item.id)
              }}
            >
              <span>{iconForTitle(item.text)}</span>
              <strong>{item.text}</strong>
            </button>
          ))}
        </nav>
      </section>
    </div>
  )
}

